from PIL import Image
from collections import deque

def clusters(path):
    im = Image.open(path)
    w,h = im.size
    px = im.load()
    dark = [[False]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            r,g,b = px[x,y]
            if r < 50 and g < 50 and b < 55:
                dark[y][x] = True
    seen = [[False]*w for _ in range(h)]
    out = []
    for y in range(h):
        for x in range(w):
            if not dark[y][x] or seen[y][x]:
                continue
            q = deque([(x,y)])
            seen[y][x] = True
            pts = []
            while q:
                cx,cy = q.popleft()
                pts.append((cx,cy))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny = cx+dx, cy+dy
                    if 0<=nx<w and 0<=ny<h and dark[ny][nx] and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((nx,ny))
            if 50 < len(pts) < 5000:
                xs = [p[0] for p in pts]
                ys = [p[1] for p in pts]
                out.append((sum(xs)/len(xs), sum(ys)/len(ys), len(pts), max(xs)-min(xs)+1, max(ys)-min(ys)+1))
    return out

for p in ["wrist_003.png","wrist_004.png","wrist_005.png"]:
    print(p, clusters("/home/robot/captures/"+p))
