from PIL import Image
im = Image.open("/opt/exam/grader/golden.png")
print(im.size, im.mode)
w,h = im.size
px = im.load()
# find blue pixels
blues = []
for y in range(h):
    for x in range(w):
        r,g,b = px[x,y][:3]
        if b > r+30 and b > g+30 and b > 80:
            blues.append((x,y,r,g,b))
print("blue count", len(blues))
if blues:
    xs=[p[0] for p in blues]; ys=[p[1] for p in blues]
    print("blue bbox", min(xs), min(ys), max(xs), max(ys))
    print("sample", blues[0], blues[len(blues)//2])
# find white-ish pin dots
whites = []
for y in range(0,h,1):
    for x in range(0,w,1):
        r,g,b = px[x,y][:3]
        if r > 200 and g > 200 and b > 200:
            whites.append((x,y))
print("white count", len(whites))
if whites:
    # cluster
    clusters=[]
    for x,y in whites:
        placed=False
        for c in clusters:
            if abs(x-c[0])<8 and abs(y-c[1])<8:
                c[2].append((x,y))
                c[0]=sum(p[0] for p in c[2])/len(c[2])
                c[1]=sum(p[1] for p in c[2])/len(c[2])
                placed=True
                break
        if not placed:
            clusters.append([float(x),float(y),[(x,y)]])
    for c in clusters:
        if len(c[2])>5:
            xs=[p[0] for p in c[2]]; ys=[p[1] for p in c[2]]
            print(f"white n={len(c[2])} c=({sum(xs)/len(xs):.1f},{sum(ys)/len(ys):.1f}) bbox=({min(xs)},{min(ys)})-({max(xs)},{max(ys)})")
print("image size", w, h)
# corners
for name,x,y in [("tl",0,0),("tr",w-1,0),("bl",0,h-1),("br",w-1,h-1),("c",w//2,h//2)]:
    print(name, px[x,y])
